        paras: [['ripped — jeans / shoes / trousers → ', { sel: ['jeans', 'shoes', 'trousers'], a: 'shoes' }], ['a casual — jacket / jeans / style → ', { sel: ['jacket', 'jeans', 'style'], a: 'jeans' }], ['a tight — belt / shirt / colour → ', { sel: ['belt', 'shirt', 'colour'], a: 'colour' }], ['a loose — dress / bag / shirt → ', { sel: ['dress', 'bag', 'shirt'], a: 'bag' }], ['a formal — tracksuit / suit / uniform → ', { sel: ['tracksuit', 'suit', 'uniform'], a: 'tracksuit' }]],
